38|export function buildUnavailableStateItems(options: IBuildModelPickerItemsOptions): IActionListItem<IActionWidgetDropdownAction>[] | undefined {
39|	const { restrictedMode, setupRequired, showAutoModel } = options.presentation;
40|	if (restrictedMode) {
41|		const enabled = !!options.actions.onRequestTrust;
42|		return [
43|			{ kind: ActionListItemKind.Header, label: localize('chat.modelPicker.restrictedMode', "Models unavailable while in Restricted mode") },
44|			{
45|				item: {
46|					id: RESTRICTED_MODE_TRUST_ACTION_ID,
47|					enabled,
48|					checked: false,
49|					class: undefined,
50|					tooltip: localize('chat.modelPicker.restrictedMode.trustTooltip', "Trust the workspace to enable models."),
51|					label: localize('chat.modelPicker.restrictedMode.trust', "Trust Workspace to enable models..."),
52|					run: () => options.actions.onRequestTrust?.(),
53|				},
54|				kind: ActionListItemKind.Action,
55|				label: localize('chat.modelPicker.restrictedMode.trust', "Trust Workspace to enable models..."),
56|				group: { title: '', icon: ThemeIcon.fromId(Codicon.workspaceTrusted.id) },
57|				disabled: !enabled,
58|				hideIcon: false,
59|			},
60|		];
61|	}
62|	if (setupRequired) {
63|		const enabled = !!options.actions.onRequestSetup;
64|		const items: IActionListItem<IActionWidgetDropdownAction>[] = [
65|			{ kind: ActionListItemKind.Header, label: localize('chat.modelPicker.setupRequired', "Sign in to use Copilot") },
66|			{
67|				item: {
68|					id: SETUP_REQUIRED_SIGN_IN_ACTION_ID,
69|					enabled,
70|					checked: false,
71|					class: undefined,
72|					tooltip: localize('chat.modelPicker.setupRequired.signInTooltip', "Sign in to GitHub Copilot to choose a model."),
73|					label: localize('chat.modelPicker.setupRequired.signIn', "Sign in to use Copilot..."),
74|					run: () => options.actions.onRequestSetup?.(),
75|				},
76|				kind: ActionListItemKind.Action,
77|				label: localize('chat.modelPicker.setupRequired.signIn', "Sign in to use Copilot..."),
78|				group: { title: '', icon: ThemeIcon.fromId(Codicon.signIn.id) },
79|				disabled: !enabled,
80|				hideIcon: false,
81|			},
82|		];
83|		if (options.presentation.showManageModelsInSetupRequired && options.manageModelsAction) {
84|			items.push(
85|				{ kind: ActionListItemKind.Separator },
86|				{
87|					item: options.manageModelsAction,
88|					kind: ActionListItemKind.Action,
89|					label: options.manageModelsAction.label,
90|					group: { title: '', icon: Codicon.blank },
91|					hideIcon: false,
92|					showAlways: true,
93|				}
94|			);
95|		}
96|		return items;
97|	}
98|	if (options.models.length > 0) {
99|		return undefined;
100|	}
101|	if (showAutoModel) {
102|		return undefined;
103|	}
104|	const entitlement = options.chatEntitlementService.entitlement;
105|	const canUpgrade = entitlement === ChatEntitlement.Free || entitlement === ChatEntitlement.EDU;
106|	const description = canUpgrade
107|		? new MarkdownString(localize('chat.modelPicker.upgradeLink', "[Upgrade](command:workbench.action.chat.upgradePlan \" \")"), { isTrusted: true })
108|		: undefined;
109|	const hover = canUpgrade ? new MarkdownString('', { isTrusted: true, supportThemeIcons: true }) : undefined;
110|	hover?.appendMarkdown(localize('chat.modelPicker.upgradeHover', "[Upgrade to GitHub Copilot Pro](command:workbench.action.chat.upgradePlan \" \") to use the best models."));
111|	return [{
112|		item: {
113|			id: 'noModels',
114|			enabled: false,
115|			checked: false,
116|			class: undefined,
117|			tooltip: localize('chat.modelPicker.noModels', "No models available"),
118|			label: localize('chat.modelPicker.noModels', "No models available"),
119|			run: () => { },
120|		},
121|		kind: ActionListItemKind.Action,
122|		label: localize('chat.modelPicker.noModels', "No models available"),
123|		description,
124|		group: { title: '', icon: ThemeIcon.fromId(Codicon.blank.id) },
125|		disabled: true,
126|		hideIcon: false,
127|		hover: hover ? { content: hover } : undefined,
128|	}];
129|}
