131|export function buildFlatModelItems(options: IBuildModelPickerItemsOptions): IActionListItem<IActionWidgetDropdownAction>[] {
132|	const items: IActionListItem<IActionWidgetDropdownAction>[] = [];
133|	if (options.models.length === 0 && options.presentation.showAutoModel) {
134|		items.push(createSyntheticAutoItem());
135|	}
136|	const autoModel = options.models.find(isAutoModel);
137|	if (autoModel) {
138|		const { action, ariaDescription } = createModelAction(autoModel, options.selectedModelId, options.actions.onSelect);
139|		items.push(createModelItem(action, autoModel, options.openerService, undefined, options.presentation.isUBB, ariaDescription));
140|	}
141|	const sortedModels = options.models
142|		.filter(model => model !== autoModel)
143|		.sort((left, right) => left.metadata.vendor.localeCompare(right.metadata.vendor) || left.metadata.name.localeCompare(right.metadata.name));
144|	for (const model of sortedModels) {
145|		const { action, ariaDescription } = createModelAction(model, options.selectedModelId, options.actions.onSelect);
146|		items.push(createModelItem(action, model, options.openerService, undefined, options.presentation.isUBB, ariaDescription, undefined, options.actions.onConfigure));
147|	}
148|	appendManageModelsAction(items, options.manageModelsAction);
149|	return items;
150|}
